examples.code:
wb = Spreadsheet("xlsx");
spreadsheetAddConditionalFormatting(wb, {
	range: "B2:B100",
	operator: "greaterThan",
	value: "100",
	format: { bold: true, bgcolor: "yellow" }
});

wb = Spreadsheet("xlsx");
spreadsheetAddConditionalFormatting(wb, {
	range: "B2:B100",
	type: "colorScale",
	colors: ["red", "yellow", "green"]
});
